import React from "react"
import { Link } from "gatsby"

const Layout = ({ location, title, wide, children }) => {
  const rootPath = `${__PATH_PREFIX__}/`
  const isRootPath = location.pathname === rootPath
  let header

  if (isRootPath) {
    header = (
      <h1 className="main-heading">
        <Link to="/">{title}</Link>
      </h1>
    )
  } else {
    header = (
      <Link className="header-link-home" to="/">
        {title}
      </Link>
    )
  }

  return (
    <div
      className={`global-wrapper${wide ? ` global-wrapper--wide` : ``}`}
      data-is-root-path={isRootPath}
    >
      <header className="global-header">{header}</header>
      <main>{children}</main>
      <footer>
        © {new Date().getFullYear()}
        {` `}
        <a
          href="https://v6monitor.com"
          target="_blank"
          rel="noopener noreferrer"
        >
          Check out v6monitor for IPv6 uptime check
        </a>
      </footer>
    </div>
  )
}

export const onRenderBody = ({ setHeadComponents }) => {
  setHeadComponents([
    <meta key="theme-color" name="theme-color" content="#051822" />,
    <meta
      key="fediverse-creator"
      name="fediverse:creator"
      content="@miyuru@ipv6.social"
    />,
  ])
}

export default Layout
